128: double nfix(void)
129: {
130:   const double r = 3.442620;
131:   static double x, y;
132: 
133:   for (;;) {
134:     x = hz * wn[iz];
135: 
136:     if (iz == 0) {
137:       do {
138:         x = -0.2904764 * log(UNI);
139:         y = -log(UNI);
140:       } while (y + y < x * x);
141: 
142:       return (hz > 0) ? r + x : -r - x;
143:     }
144: 
145:     if (fn[iz] + UNI * (fn[iz - 1] - fn[iz]) < exp(-0.5 * x * x)) {
146:       return x;
147:     }
148: 
149:     hz = SHR3;
150:     iz = hz & 127;
151: 
152:     if (abs(hz) < kn[iz]) {
